      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva a GameObject.FindObjectsOfType<GameObject>() dentro do loop Update(). Essa função realiza uma varredura linear exaustiva em toda a árvore de GameObjects da cena ativa, custando centenas de milissegundos de processamento de CPU a cada quadro.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 0;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private readonly List<GameObject> spawnedPool = new List<GameObject>();
        private static readonly int ColorProperty = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock propertyBlock;

        private void Awake()
        {
            propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var empty = new GameObject("Empty_" + i);
                spawnedPool.Add(empty);
            }
        }

        private void Update()
        {
            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            spawnedPool.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    propertyBlock.SetColor(ColorProperty, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "O método FindObjectsOfType busca objetos vasculhando toda a memória da cena do jogo. Fazer isso a cada quadro (Update) força o processador a refazer esse trabalho pesado 60 vezes por segundo. Para resolver isso, guardamos referências dos objetos em listas ou variáveis uma única vez quando eles são criados, reaproveitando essas informações em vez de procurá-las novamente."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Concatenação excessiva de strings com o operador '+' dentro de laços de repetição e criação contínua de novos arrays de objetos no Update(). Como strings são imutáveis em C#, cada concatenação aloca uma nova área na memória Heap gerenciada, acumulando quase 4MB por frame e forçando pausas longas do Garbage Collector.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestGcOptimized : MonoBehaviour
    {
        public bool enableLogging = false;
        private StringBuilder reusableBuilder;

        private void Awake()
        {
            reusableBuilder = new StringBuilder(2048);
        }

        public void ProcessDataNonAlloc(int iterations)
        {
            if (!enableLogging) return;
            reusableBuilder.Clear();
            for (int i = 0; i < iterations; i++)
            {
                reusableBuilder.Append(i);
            }
        }
    }
}",
      "explicacao_didatica": "No C#, quando você junta textos usando '+' dentro de um loop, o computador cria um texto novinho na memória e descarta o anterior. Esses textos descartados viram lixo (Garbage), e periodicamente o sistema precisa congelar o jogo por vários milissegundos para limpar essa bagunça. Utilizar classes reaproveitáveis como StringBuilder ou simplesmente evitar criar textos desnecessários no Update zera essa perda de fluidez."
    }
  ],
  "dicas_level_design": null
}

